/**
 * /solutions/ —— Cart 场景落地页索引
 *
 * 用法：这族的每一页回答**一个真实搜索词**（`GROWTH.md` §2.2 的 B 族「平台 + 场景词」），
 * 索引页只做两件事 —— ① 让爬虫一站找齐这一族的内链；② 让商家按自己的场景自选入口。
 *
 * 🔴 **准入判据**：新加一页前先回答「这个词有人搜吗？搜到的人会去装吗？」
 *    凑出来的同质落地页会被判 doorway pages（负分），宁可少而准。
 *
 * 🔴 写作红线见 `src/data/solutions.js` 文件头（AI 三条禁语 / SMS 只发单条 /
 *    不写未核实数字 / 不出现第三方实现品牌名）。
 *
 * @author 恒哥
 * @since 2026-10-13
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../../components/Layout';
import SEO from '../../components/SEO';
import { SOLUTIONS, FREE_PLAN_LIMITS } from '../../data/solutions';
import { PRODUCT_NAME, SHOPIFY_INSTALL_PAGE_PATH } from '../../constants/brand';
import '../../styles/marketing.css';
import T from '../../i18n/LocalizedText';
import { usePageI18n } from '../../i18n';

export default function SolutionsIndex(pageContext) {
  const { locale, localePath } = usePageI18n(pageContext);

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title="Solutions — abandoned checkout recovery for Shopify"
        description={`What ${PRODUCT_NAME} automates, by scenario: abandoned checkout recovery, the timed email sequence in three tones, a recovery text on the store’s own SMS account, and where cart abandonment comes from.`}
        pathname="/solutions/"
        softwareApp={false} hrefLang={locale}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow"><T id="solutions.001">Solutions</T></span>
          <h1><T id="solutions.002">Recover the checkouts you already paid to create</T></h1>
          <p className="mk-lead"><T id="solutions.003">
            Each page below takes one part of abandoned checkout recovery and explains how it
            actually works in {PRODUCT_NAME} — what fires, when it fires, and what stays on your
            side. Start from the scenario that matches your store.
          </T></p>
          <div className="mk-actions">
            <Link className="mk-btn mk-btn-primary" to={SHOPIFY_INSTALL_PAGE_PATH}><T id="solutions.004">
              Install {PRODUCT_NAME} free
            </T></Link>
            <Link className="mk-btn mk-btn-secondary" to={localePath("/pricing/")}><T id="solutions.005">
              See pricing
            </T></Link>
          </div>
        </header>

        <section className="mk-section">
          <div className="mk-grid">
            {SOLUTIONS.map((s) => (
              <article className="mk-card" key={s.slug}>
                <span className="mk-card-tag">{s.eyebrow}</span>
                <h3>{s.name}</h3>
                <p>{s.lede}</p>
                <Link className="mk-card-link" to={`/solutions/${s.slug}/`}><T id="solutions.006">
                  Read more &rarr;
                </T></Link>
              </article>
            ))}
          </div>
        </section>

        <div className="mk-scope">
          <T id="solutions.007"><strong>Scope.</strong> Everything described here is recovery for Shopify: detection of
          abandoned checkouts, timed email in Friendly, Professional, or Urgency, and a recovery
          text on the store’s own SMS account. The email is sent by the app; the text goes out
          through the provider account connected inside the app. The Free plan includes both
          channels, with{' '}
          {FREE_PLAN_LIMITS.carts} abandoned carts and {FREE_PLAN_LIMITS.emails} recovery emails per
          month.
        </T></div>
      </div>
    </Layout>
  );
}
